// 48 pixels to a ring, so one percent is a little under half a pixel.
const PIXELS = 48;

// Which slot to own. Slot 0 belongs to the animation buttons on the device
// page and slot 1 to send_forecast, so start your own scenes at 2.
const SLOT = 3;

const pct = Number(msg.payload);
if (Number.isNaN(pct)) {
    // unavailable, unknown, or a restart in progress -- draw nothing rather
    // than drawing something wrong
    return null;
}

// Floor, then clamp: a length of 0 is invalid and the service call would
// fail, and a length above 48 runs off the end of the ring.
let length = Math.floor((Math.min(Math.max(pct, 0), 100) / 100) * PIXELS);
length = Math.min(Math.max(length, 1), PIXELS);

// The palette is fixed -- these are names from it, not arbitrary colours.
let color = 'lime';
if (pct < 20) {
    color = 'red';
} else if (pct < 50) {
    color = 'dark_orange';
}

msg.action = 'glance_clock.set_leds';
msg.payload = {
    slot: SLOT,
    mode: 'watchface',
    segments: [
        // Painted in order, so the dim track has to come first and the
        // value is drawn over it.
        { start: 0, length: PIXELS, ring: 0, color: 'dark_green' },
        { start: 0, length: length, ring: 0, color: color },
    ],
};
return msg;

// A scene stays in its slot and replays until something clears it. Ending
// a lifetime does not remove it, and neither does sending nothing.
msg.action = 'glance_clock.clear_leds';
msg.payload = { slot: 3 };
return msg;
